int logfmt_parse_multi(const char *in, char **keys, char **vals, size_t max_pairs) {
    size_t pair_count = 0;
    const char *pair_start = in;

    while (pair_start != NULL && pair_count < max_pairs) {
        const char *eq = strchr(pair_start, '=');
        if (!eq) break;

        size_t klen = (size_t)(eq - pair_start);
        keys[pair_count] = malloc(klen + 1);
        strncpy(keys[pair_count], pair_start, klen);
        keys[pair_count][klen] = '\0';

        const char *val_start = eq + 1;
        if (*val_start == '"') {
            const char *quote = strchr(val_start + 1, '"');
            if (quote) {
                size_t vlen = (size_t)(quote - val_start - 1);
                vals[pair_count] = malloc(vlen + 1);
                strncpy(vals[pair_count], val_start + 1, vlen);
                vals[pair_count][vlen] = '\0';
                pair_start = quote + 1;
            } else {
                break;
            }
        } else {
            size_t vlen = 0;
            while (val_start[vlen] != ' ' && val_start[vlen] != '\0') vlen++;
            vals[pair_count] = malloc(vlen + 1);
            strncpy(vals[pair_count], val_start, vlen);
            vals[pair_count][vlen] = '\0';
            pair_start = strchr(eq, ' ') + 1;
        }

        pair_count++;
    }

    return pair_count;
}

