void logfmt_trim(char *s) {
    if (s == NULL) return;

    // Trim trailing spaces
    char *end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) {
        end--;
    }
    *(end + 1) = '\0';
}

