    int n = snprintf(out, out_sz, "%s=%s", k, v);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

int logfmt_format(char *out, size_t out_sz, const char *key, const char *val) {
    return _write_pair(out, out_sz, key, val);
}

int logfmt_copy(char *dst, size_t dst_sz, const char *src) {
    if (dst_sz == 0) return -1;
    strncpy(dst, src, dst_sz - 1);
    dst[dst_sz - 1] = '\0';
    return 0;
}

int logfmt_parse(const char *in, char *key_out, size_t k_sz, char *val_out, size_t v_sz) {
    const char *eq = strchr(in, '=');
    if (!eq) return -1;
    size_t klen = (size_t)(eq - in);
    if (klen >= k_sz) klen = k_sz - 1;
    strncpy(key_out, in, klen);
    key_out[klen] = '\0';

    const char *val_start = eq + 1;
    if (*val_start == '"') {
        const char *quote = strchr(val_start + 1, '"');
        if (quote) {
            size_t vlen = (size_t)(quote - val_start - 1);
            if (vlen >= v_sz) vlen = v_sz - 1;
            strncpy(val_out, val_start + 1, vlen);
            val_out[vlen] = '\0';
            return 0;
        }
    } else {
        size_t vlen = 0;
        while (val_start[vlen] != ' ' && val_start[vlen] != '\0') vlen++;
        if (vlen >= v_sz) vlen = v_sz - 1;
        strncpy(val_out, val_start, vlen);
        val_out[vlen] = '\0';
        return 0;
    }

    return -1;
}

int logfmt_format_ts(char *out, size_t out_sz, const char *key, const char *val, long ts) {
    int n = snprintf(out, out_sz, "%s=%s ts=%ld", key, val, ts);
    return (n > 0 && (size_t)n < out_sz) ? 0 : -1;
}

size_t logfmt_len(const char *key, const char *val) {
    return strlen(key) + strlen(val) + 2; // +2 for '=' and '\0'
}

int logfmt_copy_upper(char *dst, size_t dst_sz, const char *src) {
    if (dst_sz == 0) return -1;
    for (size_t i = 0; src[i] != '\0' && i < dst_sz - 1; i++) {
        dst[i] = toupper(src[i]);
    }
    dst[dst_sz - 1] = '\0';
    return 0;
}

int logfmt_append(char *buf, size_t buf_sz, const char *key, const char *val) {
    size_t len = strlen(buf);
    if (len + logfmt_len(key, val) + 1 > buf_sz) return -1;
    buf[len++] = ' ';
    return _write_pair(&buf[len], buf_sz - len, key, val);
}

void logfmt_trim(char *s) {
    if (s == NULL) return;

    // Trim trailing spaces
    char *end = s + strlen(s) - 1;
    while (end > s && isspace((unsigned char)*end)) {
        end--;
    }
    *(end + 1) = '\0';
}

int logfmt_nth_token(const char *line, int n, char *out, size_t out_sz) {
    if (n < 0 || !line || !out || out_sz == 0) return -1;

    const char *token = line;
    for (int i = 0; i < n; i++) {
        token = strchr(token, ' ');
        if (!token) return -1;
        token++; // Move past the space
    }

    const char *end = strchr(token, ' ');
    if (!end) end = line + strlen(line);

    size_t len = (size_t)(end - token);
    if (len >= out_sz) len = out_sz - 1;
    strncpy(out, token, len);
    out[len] = '\0';

    return 0;
}

